import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import { API_BASE_URL } from './config/api';


// En la app móvil el backend tiene otro origen; PHP necesita que la sesión
// viaje también en las llamadas que antes dependían del mismo localhost.
const fetchOriginal = window.fetch.bind(window);
window.fetch = (input, init = {}) => {
    const url = typeof input === 'string' ? input : input.url;
    if (url.startsWith(API_BASE_URL) && init.credentials === undefined) {
        return fetchOriginal(input, { ...init, credentials: 'include' });
    }
    return fetchOriginal(input, init);
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
    <App />
);
